  async function save(e){e.preventDefault();try{const sourceOriginal=parseMoney(form.amount),sourceRemaining=form.remaining?nonNegativeMoney(form.remaining):sourceOriginal,quote=await getCurrencyQuote(form.currency,base),original=convertMinorUnits(sourceOriginal,quote.rate),remaining=convertMinorUnits(sourceRemaining,quote.rate),plannedAmount=form.planned?nonNegativeMoney(form.planned):0;await change(s=>{const stamp=new Date().toISOString(),old=editing?s.debts.find(x=>x.id===editing):null,record={name:form.name.trim(),startedOn:old?.startedOn||today(),createdAt:old?.createdAt||stamp,original,remaining,sourceCurrency:form.currency,sourceOriginal,sourceRemaining,exchangeRate:quote.rate,rateDate:quote.date,plannedAmount,dueDate:form.dueDate,frequency:form.frequency,priority:form.priority,notes:form.notes,status:remaining?'open':'paid',repaymentPlanStatus:remaining?(old?.repaymentPlanStatus==='completed'?'not_started':old?.repaymentPlanStatus||'not_started'):'completed'};if(editing)Object.assign(old,record);else s.debts.push({id:id(),...record});return s},editing?'Debt updated':'Debt added');setEditing('');setForm(newDebtDraft(data.settings))}catch(err){setError(err.message)}}
  async function pay(debt){const source=debt.sourceCurrency||base,planned=plannedDebtPayment(debt);let initialAmount=0;if(planned>0){if(source===base)initialAmount=Math.min(planned,debt.sourceRemaining??debt.remaining);else{const quote=await getCurrencyQuote(base,source);initialAmount=Math.min(convertMinorUnits(planned,quote.rate),debt.sourceRemaining??debt.sourceOriginal??debt.remaining)}}requestMoney({title:`Record payment to ${debt.name}`,description:`Outstanding: ${formatMoney(debt.sourceRemaining??debt.remaining,source)}. This records an actual payment and reduces the balance.`,currency:source,convertTo:base,initialAmount,dateField:true,initialDate:today(),label:`Payment amount in ${source}`,submitLabel:'Record payment',onSubmit:async(sourceAmount,paymentDate)=>{const quote=await getCurrencyQuote(source,base),amount=convertMinorUnits(sourceAmount,quote.rate);if(amount>debt.remaining)throw new Error('Payment cannot exceed the remaining balance.');return change(s=>{const d=s.debts.find(x=>x.id===debt.id);if(amount>d.remaining)throw new Error('Payment cannot exceed the remaining balance.');d.remaining-=amount;if(Number.isSafeInteger(d.sourceRemaining))d.sourceRemaining=Math.max(0,d.sourceRemaining-sourceAmount);d.status=d.remaining?'open':'paid';if(!d.remaining){d.repaymentPlanStatus='completed';for(const r of s.allocationRules||[])if(r.targetType==='debt'&&r.targetId===d.id)r.active=false}const tx=id();s.debtPayments.push({id:id(),debtId:d.id,amount,sourceAmount,sourceCurrency:source,exchangeRate:quote.rate,rateDate:quote.date,date:paymentDate,transactionId:tx});s.transactions.push({id:tx,title:`Payment to ${d.name}`,amount,type:'debt',targetId:d.id,categoryId:'',date:paymentDate,note:`${formatMoney(sourceAmount,source)} at ${quote.rate}`,paymentMethod:'',createdAt:new Date().toISOString()});return s},'Payment recorded')}})}
